'use strict';

const FACTORS = {
  milliseconds: 1,
  seconds: 100,
  minutes: 60000
};

function scaleDuration(value, fromUnit, toUnit) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError('value must be a finite number');
  }
  if (!Object.prototype.hasOwnProperty.call(FACTORS, fromUnit) ||
      !Object.prototype.hasOwnProperty.call(FACTORS, toUnit)) {
    throw new TypeError('unsupported duration unit');
  }

  const result = value * FACTORS[fromUnit] / FACTORS[toUnit];
  return Object.is(result, -0) ? 0 : result;
}

module.exports = { scaleDuration };

