'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['scaleDuration']);
const { scaleDuration } = api;

assert.equal(scaleDuration(2, 'seconds', 'milliseconds'), 2000);
assert.equal(scaleDuration(120000, 'milliseconds', 'minutes'), 2);
assert.equal(scaleDuration(1.5, 'minutes', 'seconds'), 90);
assert.equal(scaleDuration(-2.5, 'seconds', 'milliseconds'), -2500);
assert.equal(scaleDuration(7.25, 'minutes', 'minutes'), 7.25);
assert.equal(scaleDuration(0, 'milliseconds', 'seconds'), 0);
const zero = scaleDuration(-0, 'seconds', 'seconds');
assert.equal(zero, 0);
assert.equal(Object.is(zero, -0), false);

for (const value of [NaN, Infinity, -Infinity, '1', null, undefined]) {
  assert.throws(() => scaleDuration(value, 'seconds', 'minutes'), TypeError);
}
for (const unit of ['second', 'SECONDS', '', null, undefined, 1]) {
  assert.throws(() => scaleDuration(1, unit, 'seconds'), TypeError);
  assert.throws(() => scaleDuration(1, 'seconds', unit), TypeError);
}

